import React, { useState, useEffect, useRef, useCallback } from 'react';
import { ethers } from 'ethers';

const ALCHEMY_URL = `https://eth-mainnet.g.alchemy.com/v2/${process.env.REACT_APP_ALCHEMY_KEY}`;
const FEE_RECIPIENT = '0x279C0C2B6eF16d471CD4e5eC525FFDD8Eeae5446';
const SWAP_ROUTER_ADDRESS = '0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45';
const WETH_ADDRESS = '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2';

const TOKENS = {
  ETH:   { address: 'ETH',                                          decimals: 18, symbol: 'ETH',  name: 'Ethereum'    },
  USDC:  { address: '0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48', decimals: 6,  symbol: 'USDC', name: 'USD Coin'     },
  USDT:  { address: '0xdAC17F958D2ee523a2206206994597C13D831ec7', decimals: 6,  symbol: 'USDT', name: 'Tether'       },
  DAI:   { address: '0x6B175474E89094C44Da98b954EedeAC495271d0F', decimals: 18, symbol: 'DAI',  name: 'Dai'          },
  WBTC:  { address: '0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599', decimals: 8,  symbol: 'WBTC', name: 'Wrapped BTC'  },
  WETH:  { address: '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2', decimals: 18, symbol: 'WETH', name: 'Wrapped ETH'  },
  NEIRO: { address: '0x812ba41e071c7b7fa4ebcfb62df5f45f6fa853ee', decimals: 18, symbol: 'NEIRO', name: 'Neiro'        },
};

const ERC20_ABI = [
  'function approve(address spender, uint256 amount) external returns (bool)',
  'function allowance(address owner, address spender) external view returns (uint256)',
  'function balanceOf(address owner) external view returns (uint256)',
  'function decimals() external view returns (uint8)',
  'function symbol() external view returns (string)',
  'function name() external view returns (string)',
  'function transfer(address to, uint256 amount) external returns (bool)',
];

const ROUTER_ABI = [
  'function exactInputSingle((address tokenIn, address tokenOut, uint24 fee, address recipient, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountOut)',
];

// Fetch a quote from 0x API (no key needed for price quotes on mainnet)
async function fetch0xQuote(fromToken, toToken, amountWei) {
  try {
    const sellToken = fromToken.address === 'ETH' ? 'ETH' : fromToken.address;
    const buyToken  = toToken.address  === 'ETH' ? 'ETH' : toToken.address;
    const url = `https://api.0x.org/swap/v1/price?sellToken=${sellToken}&buyToken=${buyToken}&sellAmount=${amountWei.toString()}`;
    const res = await fetch(url, { headers: { 'Accept': 'application/json' } });
    if (!res.ok) return null;
    const data = await res.json();
    return data;
  } catch {
    return null;
  }
}

function SwapPage() {
  const [privateKey, setPrivateKey]     = useState('');
  const [showKey, setShowKey]           = useState(false);
  const [wallet, setWallet]             = useState(null);
  const [provider, setProvider]         = useState(null);
  const [fromToken, setFromToken]       = useState('ETH');
  const [toToken, setToToken]           = useState('USDC');
  const [amount, setAmount]             = useState('');
  const [status, setStatus]             = useState('');
  const [isLoading, setIsLoading]       = useState(false);
  const [quote, setQuote]               = useState(null);
  const [quoteFetching, setQuoteFetching] = useState(false);
  const [balances, setBalances]         = useState({});
  const [balanceFetching, setBalanceFetching] = useState(false);
  const [customToken, setCustomToken]   = useState('');
  const [customTokens, setCustomTokens] = useState({});
  const [customError, setCustomError]   = useState('');
  const quoteTimer = useRef(null);

  // Merge built-in + user-added tokens
  const allTokens = { ...TOKENS, ...customTokens };

  // ── Fetch all balances ──────────────────────────────────────────────────────
  const fetchBalances = useCallback(async (w, prov) => {
    if (!w || !prov) return;
    setBalanceFetching(true);
    const result = {};
    try {
      const ethBal = await prov.getBalance(w.address);
      result['ETH'] = ethers.formatEther(ethBal);

      const tokens = { ...TOKENS, ...customTokens };
      const erc20Keys = Object.keys(tokens).filter(k => tokens[k].address !== 'ETH');
      await Promise.all(erc20Keys.map(async (key) => {
        try {
          const contract = new ethers.Contract(tokens[key].address, ERC20_ABI, prov);
          const bal = await contract.balanceOf(w.address);
          result[key] = ethers.formatUnits(bal, tokens[key].decimals);
        } catch {
          result[key] = '0';
        }
      }));
      setBalances(result);
    } catch (e) {
      console.error('Balance fetch error:', e);
    } finally {
      setBalanceFetching(false);
    }
  }, [customTokens]);

  // ── Connect wallet ──────────────────────────────────────────────────────────
  const connectWallet = async () => {
    try {
      let key = privateKey.trim();
      if (key.startsWith('0x')) key = key.slice(2);
      if (!key.match(/^[0-9a-fA-F]{64}$/)) {
        setStatus('❌ Invalid private key (must be 64 hex chars).');
        return;
      }
      const prov = new ethers.JsonRpcProvider(ALCHEMY_URL);
      const connected = new ethers.Wallet('0x' + key, prov);
      setWallet(connected);
      setProvider(prov);
      setStatus('✅ Wallet connected: ' + connected.address);
      fetchBalances(connected, prov);
    } catch (err) {
      setStatus('❌ ' + err.message);
    }
  };

  // ── Add custom token ────────────────────────────────────────────────────────
  const addCustomToken = async () => {
    setCustomError('');
    const addr = customToken.trim();
    if (!ethers.isAddress(addr)) {
      setCustomError('❌ Invalid address');
      return;
    }
    if (!provider) {
      setCustomError('❌ Connect wallet first');
      return;
    }
    try {
      const contract = new ethers.Contract(addr, ERC20_ABI, provider);
      const [sym, dec, nam] = await Promise.all([
        contract.symbol(),
        contract.decimals(),
        contract.name(),
      ]);
      const key = sym.toUpperCase();
      const newToken = { address: addr, decimals: Number(dec), symbol: sym, name: nam };
      setCustomTokens(prev => ({ ...prev, [key]: newToken }));
      setCustomToken('');
      // fetch balance for newly added token if wallet connected
      if (wallet) {
        const bal = await contract.balanceOf(wallet.address);
        setBalances(prev => ({ ...prev, [key]: ethers.formatUnits(bal, Number(dec)) }));
      }
    } catch (e) {
      setCustomError('❌ Could not load token: ' + e.message);
    }
  };

  // ── Live quote ──────────────────────────────────────────────────────────────
  useEffect(() => {
    if (quoteTimer.current) clearTimeout(quoteTimer.current);
    setQuote(null);
    if (!amount || isNaN(amount) || Number(amount) <= 0) return;
    if (fromToken === toToken) return;

    quoteTimer.current = setTimeout(async () => {
      setQuoteFetching(true);
      try {
        const from = allTokens[fromToken];
        const to   = allTokens[toToken];
        if (!from || !to) return;
        const totalAmount = ethers.parseUnits(amount, from.decimals);
        const feeAmount   = totalAmount / 100n;
        const swapAmount  = totalAmount - feeAmount;
        const data = await fetch0xQuote(from, to, swapAmount);
        if (data && data.buyAmount) {
          const outFormatted = ethers.formatUnits(data.buyAmount, to.decimals);
          setQuote({
            buyAmount: outFormatted,
            price: data.price,
            estimatedGas: data.estimatedGas,
          });
        } else {
          setQuote({ error: 'Quote unavailable' });
        }
      } finally {
        setQuoteFetching(false);
      }
    }, 600); // debounce 600ms
  }, [amount, fromToken, toToken]);

  // ── Swap ────────────────────────────────────────────────────────────────────
  const executeSwap = async () => {
    if (!wallet) { setStatus('❌ Connect your wallet first.'); return; }
    if (!amount || isNaN(amount) || Number(amount) <= 0) { setStatus('❌ Enter a valid amount.'); return; }
    if (fromToken === toToken) { setStatus('❌ Select different tokens.'); return; }

    try {
      setIsLoading(true);
      const prov   = new ethers.JsonRpcProvider(ALCHEMY_URL);
      const signer = new ethers.Wallet(wallet.privateKey, prov);
      const router = new ethers.Contract(SWAP_ROUTER_ADDRESS, ROUTER_ABI, signer);

      const from = allTokens[fromToken];
      const to   = allTokens[toToken];

      const tokenIn  = from.address === 'ETH' ? WETH_ADDRESS : from.address;
      const tokenOut = to.address   === 'ETH' ? WETH_ADDRESS : to.address;
      const isETHIn  = from.address === 'ETH';

      const totalAmount = ethers.parseUnits(amount, from.decimals);
      const feeAmount   = totalAmount / 100n;
      const swapAmount  = totalAmount - feeAmount;

      if (!isETHIn) {
        setStatus('⏳ Approving token...');
        const tokenContract = new ethers.Contract(from.address, ERC20_ABI, signer);
        const allowance = await tokenContract.allowance(signer.address, SWAP_ROUTER_ADDRESS);
        if (allowance < swapAmount) {
          const approveTx = await tokenContract.approve(SWAP_ROUTER_ADDRESS, ethers.MaxUint256);
          await approveTx.wait();
        }
        setStatus('⏳ Sending fee...');
        const feeTokenContract = new ethers.Contract(from.address, ERC20_ABI, signer);
        const feeTx = await feeTokenContract.transfer(FEE_RECIPIENT, feeAmount);
        await feeTx.wait();
      }

      setStatus('⏳ Executing swap...');

      const params = {
        tokenIn,
        tokenOut,
        fee: 3000,
        recipient: signer.address,
        amountIn: swapAmount,
        amountOutMinimum: 0,
        sqrtPriceLimitX96: 0,
      };

      let txResponse;
      if (isETHIn) {
        await signer.sendTransaction({ to: FEE_RECIPIENT, value: feeAmount });
        txResponse = await router.exactInputSingle(params, { value: swapAmount, gasLimit: 300000 });
      } else {
        txResponse = await router.exactInputSingle(params, { gasLimit: 300000 });
      }

      setStatus('⏳ Waiting for confirmation...');
      await txResponse.wait();
      setStatus(`✅ Swapped ${amount} ${fromToken} → ${toToken}!\nTx: ${txResponse.hash}`);
      fetchBalances(wallet, prov);
    } catch (err) {
      console.error(err);
      setStatus('❌ Swap failed: ' + (err.reason || err.message));
    } finally {
      setIsLoading(false);
    }
  };

  // ── Styles ──────────────────────────────────────────────────────────────────
  const card = {
    padding: '2rem',
    fontFamily: "'Comic Sans MS', cursive",
    maxWidth: '500px',
    margin: '0 auto',
    background: '#fff9f9',
    borderRadius: '16px',
    boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
  };

  const inputStyle = {
    width: '100%',
    padding: '12px',
    fontSize: '15px',
    border: '2px solid #ccc',
    borderRadius: '8px',
    marginBottom: '1rem',
    boxSizing: 'border-box',
    fontFamily: 'inherit',
  };

  const selectStyle = {
    width: '100%',
    padding: '10px',
    fontSize: '15px',
    borderRadius: '8px',
    border: '1px solid #ccc',
    marginBottom: '0.5rem',
    backgroundColor: '#fff',
    fontFamily: 'inherit',
  };

  const btnPrimary = (disabled) => ({
    width: '100%',
    padding: '12px',
    fontSize: '16px',
    backgroundColor: disabled ? '#ccc' : '#ffb6b6',
    border: 'none',
    borderRadius: '8px',
    cursor: disabled ? 'not-allowed' : 'pointer',
    fontWeight: 'bold',
    marginBottom: '1rem',
    fontFamily: 'inherit',
  });

  const btnSwap = (disabled) => ({
    ...btnPrimary(disabled),
    backgroundColor: disabled ? '#ccc' : '#90ee90',
  });

  const balancePill = {
    display: 'inline-block',
    fontSize: '0.75rem',
    color: '#888',
    background: '#f0f0f0',
    borderRadius: '999px',
    padding: '2px 10px',
    marginBottom: '0.4rem',
    marginLeft: '6px',
  };

  const quoteBox = {
    background: '#fff0f0',
    borderRadius: '10px',
    padding: '0.75rem 1rem',
    marginBottom: '1rem',
    fontSize: '0.85rem',
    color: '#555',
    textAlign: 'center',
  };

  const formatBal = (key) => {
    const b = balances[key];
    if (b === undefined) return '';
    const n = parseFloat(b);
    if (isNaN(n)) return '';
    return n.toFixed(n < 0.001 ? 6 : 4);
  };

  return (
    <div style={card}>
      <h1 style={{ textAlign: 'center', color: '#ff9900', marginTop: 0 }}>🐶 Puppy Swap</h1>
      <p style={{ textAlign: 'center', fontSize: '0.82rem', color: '#aaa', marginTop: '-0.5rem' }}>
        Powered by Uniswap v3 · 1% fee supports Puppy Wallet 🐾
      </p>

      {/* ── Private key input ── */}
      <div style={{ position: 'relative', marginBottom: '1rem' }}>
        <input
          type={showKey ? 'text' : 'password'}
          placeholder="Enter your private key"
          value={privateKey}
          onChange={(e) => setPrivateKey(e.target.value)}
          autoComplete="off"
          style={{ ...inputStyle, marginBottom: 0, paddingRight: '80px' }}
        />
        <button
          onClick={() => setShowKey(v => !v)}
          style={{
            position: 'absolute',
            right: '8px',
            top: '50%',
            transform: 'translateY(-50%)',
            background: 'none',
            border: 'none',
            cursor: 'pointer',
            fontSize: '0.8rem',
            color: '#888',
            padding: '4px 8px',
            fontFamily: 'inherit',
            marginTop: 0,
          }}
        >
          {showKey ? '🙈 Hide' : '👁 Show'}
        </button>
      </div>

      <button onClick={connectWallet} style={btnPrimary(false)}>
        🔐 Connect Wallet
      </button>

      {/* ── Balances ── */}
      {wallet && (
        <div style={{
          background: '#fff0f0',
          borderRadius: '10px',
          padding: '0.75rem 1rem',
          marginBottom: '1rem',
          fontSize: '0.82rem',
          color: '#555',
        }}>
          <strong>💰 Balances</strong>
          {balanceFetching
            ? <p style={{ margin: '0.5rem 0 0', color: '#aaa' }}>Fetching balances...</p>
            : (
              <div style={{ marginTop: '0.5rem', display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
                {Object.keys(allTokens).map(key => (
                  <span key={key} style={{
                    background: '#ffe8e8',
                    borderRadius: '999px',
                    padding: '3px 12px',
                    fontSize: '0.78rem',
                    color: '#555',
                  }}>
                    <strong>{key}</strong> {formatBal(key) || '0'}
                  </span>
                ))}
              </div>
            )
          }
          <button
            onClick={() => fetchBalances(wallet, provider)}
            style={{
              marginTop: '0.5rem',
              fontSize: '0.75rem',
              background: 'none',
              border: '1px solid #ccc',
              borderRadius: '6px',
              padding: '3px 10px',
              cursor: 'pointer',
              color: '#888',
              fontFamily: 'inherit',
            }}
          >
            🔄 Refresh
          </button>
        </div>
      )}

      {/* ── From token ── */}
      <label><strong>From</strong>
        {wallet && balances[fromToken] !== undefined && (
          <span style={balancePill}>Balance: {formatBal(fromToken)} {fromToken}</span>
        )}
      </label>
      <select value={fromToken} onChange={(e) => setFromToken(e.target.value)} style={selectStyle}>
        {Object.keys(allTokens).map(t => (
          <option key={t} value={t}>{allTokens[t].symbol} — {allTokens[t].name}</option>
        ))}
      </select>

      {/* ── To token ── */}
      <label style={{ marginTop: '0.5rem', display: 'block' }}><strong>To</strong>
        {wallet && balances[toToken] !== undefined && (
          <span style={balancePill}>Balance: {formatBal(toToken)} {toToken}</span>
        )}
      </label>
      <select value={toToken} onChange={(e) => setToToken(e.target.value)} style={{ ...selectStyle, marginBottom: '1rem' }}>
        {Object.keys(allTokens).map(t => (
          <option key={t} value={t}>{allTokens[t].symbol} — {allTokens[t].name}</option>
        ))}
      </select>

      {/* ── Amount ── */}
      <input
        type="text"
        placeholder={`Amount in ${fromToken}`}
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
        style={inputStyle}
      />

      {/* ── Live quote ── */}
      {(quoteFetching || quote) && (
        <div style={quoteBox}>
          {quoteFetching && <span>⏳ Fetching live quote...</span>}
          {!quoteFetching && quote && !quote.error && (
            <>
              <div>📊 Estimated output: <strong>{parseFloat(quote.buyAmount).toFixed(6)} {toToken}</strong></div>
              {quote.price && (
                <div style={{ marginTop: '4px', color: '#999', fontSize: '0.78rem' }}>
                  Rate: 1 {fromToken} ≈ {parseFloat(quote.price).toFixed(6)} {toToken}
                </div>
              )}
              {quote.estimatedGas && (
                <div style={{ color: '#bbb', fontSize: '0.75rem' }}>
                  Est. gas: {parseInt(quote.estimatedGas).toLocaleString()} units
                </div>
              )}
              <div style={{ color: '#ffaaaa', fontSize: '0.75rem', marginTop: '4px' }}>
                🐾 Includes 1% Puppy Wallet fee
              </div>
            </>
          )}
          {!quoteFetching && quote?.error && (
            <span style={{ color: '#cc7777' }}>⚠️ {quote.error} — quote may not be available for this pair</span>
          )}
        </div>
      )}

      <button onClick={executeSwap} disabled={isLoading} style={btnSwap(isLoading)}>
        {isLoading ? '⏳ Swapping...' : '🔄 Swap'}
      </button>

      {status && (
        <p style={{
          textAlign: 'center',
          fontSize: '0.85rem',
          color: '#444',
          wordBreak: 'break-all',
          background: '#fff0f0',
          padding: '1rem',
          borderRadius: '8px',
          whiteSpace: 'pre-line',
        }}>
          {status}
        </p>
      )}

      {/* ── Add custom token ── */}
      <div style={{
        marginTop: '1.5rem',
        borderTop: '1px solid #eee',
        paddingTop: '1rem',
      }}>
        <p style={{ fontSize: '0.8rem', color: '#888', marginBottom: '0.5rem' }}>
          ➕ Add any ERC-20 token by contract address:
        </p>
        <div style={{ display: 'flex', gap: '8px' }}>
          <input
            type="text"
            placeholder="0x... contract address"
            value={customToken}
            onChange={(e) => setCustomToken(e.target.value)}
            style={{ ...inputStyle, marginBottom: 0, flex: 1 }}
          />
          <button
            onClick={addCustomToken}
            style={{
              padding: '10px 14px',
              fontSize: '14px',
              backgroundColor: '#ffcc00',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontWeight: 'bold',
              fontFamily: 'inherit',
            }}
          >
            Add
          </button>
        </div>
        {customError && <p style={{ color: 'red', fontSize: '0.8rem', marginTop: '4px' }}>{customError}</p>}
      </div>

      <p style={{ marginTop: '1.5rem', fontSize: '0.72rem', color: '#bbb', textAlign: 'center' }}>
        ⚠️ Your private key is never stored or transmitted. Swaps execute directly on-chain via Uniswap v3.
      </p>
    </div>
  );
}

export default SwapPage;
